-- Continues the rolled-back 0276 fixture before its activation section.
do $$declare a uuid:='a2760000-0000-4000-8000-000000000001';t uuid:='b2760000-0000-4000-8000-000000000001';r uuid:='e2760000-0000-4000-8000-000000000002';m uuid:='d2760000-0000-4000-8000-000000000011';c uuid:='d2760000-0000-4000-8000-000000000012';req jsonb;oldpins jsonb;newpins jsonb;outcome jsonb;replay jsonb;begin
 insert into app.tournament_setup_official_versions(id,tournament_id,setup_revision_id,profile_id,role)values('e2760000-0000-4000-8000-000000000010',t,r,a,'director');
 select jsonb_build_object('expectedVersion',version,'expectedSettingsFingerprint',app.event_prize_settings_digest_v2(app.event_prize_settings_v2(t,c)),'schedule',schedule_payload,'reason','TEST ONLY updated Consolation fee','reviewed',true)into req from app.setup_prize_schedule_versions_v2 where tournament_id=t and client_row_id=c order by version desc limit 1;
 outcome:=public.save_event_prize_declaration_v2(a,t,c,req,'d2890000-0000-4000-8000-000000000001');if outcome->>'status'<>'event_prize_declaration_saved_v2' then raise exception 'consolation declaration %',outcome;end if;
 oldpins:=app.current_event_prize_activation_pins_v1(t,r,2);if jsonb_array_length(oldpins)<>2 then raise exception 'wrong pin count %',oldpins;end if;
 if public.get_event_prize_pinned_activation_capability_v1(a,t) is distinct from '{"available":true,"protocol":"event-prize-pins-v1","hasV2Bindings":false}'::jsonb or public.get_event_prize_pinned_activation_capability_v1('a2760000-0000-4000-8000-000000000002',t) is not null or has_function_privilege('authenticated','public.get_event_prize_pinned_activation_capability_v1(uuid,uuid)','execute') then raise exception 'capability authorization failed';end if;
 if public.activate_tournament_setup_v2(a,t,r,2,'d2890000-0000-4000-8000-000000000002')->>'code'<>'declaration_pins_required' then raise exception 'unpinned V2 activation accepted';end if;
 if public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,oldpins-1,'d2890000-0000-4000-8000-000000000003')->>'code'<>'declaration_pins_changed' then raise exception 'missing pin accepted';end if;
 if public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,oldpins||jsonb_build_array(oldpins->0),'d2890000-0000-4000-8000-000000000007')->>'code'<>'declaration_pins_changed' then raise exception 'duplicate pin accepted';end if;
 if public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,oldpins||jsonb_build_array(jsonb_build_object('clientRowId','d2890000-0000-4000-8000-000000000999','declarationId','d2890000-0000-4000-8000-000000000998','settingsFingerprint',repeat('0',64))),'d2890000-0000-4000-8000-000000000008')->>'code'<>'declaration_pins_changed' then raise exception 'extra pin accepted';end if;
 select jsonb_build_object('expectedVersion',version,'expectedSettingsFingerprint',settings_fingerprint,'schedule',jsonb_set(schedule_payload,'{cohorts,0,weight}','5'),'reason','TEST ONLY new formula without setup change','reviewed',true)into req from app.setup_prize_schedule_versions_v2 where tournament_id=t and client_row_id=m order by version desc limit 1;
 outcome:=public.save_event_prize_declaration_v2(a,t,m,req,'d2890000-0000-4000-8000-000000000004');if outcome->>'status'<>'event_prize_declaration_saved_v2' then raise exception 'new Main declaration %',outcome;end if;
 if public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,oldpins,'d2890000-0000-4000-8000-000000000005')->>'code'<>'declaration_pins_changed' then raise exception 'unreviewed newer formula accepted';end if;
 if exists(select 1 from app.tournament_setup_activations where tournament_id=t)then raise exception 'stale request partially activated';end if;
 newpins:=app.current_event_prize_activation_pins_v1(t,r,2);outcome:=public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,newpins,'d2890000-0000-4000-8000-000000000006');
 if outcome->>'status'<>'tournament_setup_activated' or outcome->>'registrationState'<>'open' then raise exception 'pinned activation %',outcome;end if;
 if (select count(*)from app.event_prize_schedule_bindings_v2 where tournament_id=t)<>2 then raise exception 'wrong binding count';end if;
 if public.get_event_prize_pinned_activation_capability_v1(a,t)->'hasV2Bindings' is distinct from'true'::jsonb then raise exception 'active V2 binding not reported';end if;
 if exists(select 1 from app.event_prize_schedule_bindings_v2 b where b.tournament_id=t and not exists(select 1 from jsonb_array_elements(newpins)p where p->>'clientRowId'=b.client_row_id::text and p->>'declarationId'=b.declaration_version_id::text and p->>'settingsFingerprint'=b.settings_fingerprint))then raise exception 'bound formula differs from pins';end if;
 replay:=public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,newpins,'d2890000-0000-4000-8000-000000000006');if replay is distinct from outcome then raise exception 'exact replay changed';end if;
 if public.finalize_tournament_setup_pinned_v2(a,t,r,2,true,oldpins,'d2890000-0000-4000-8000-000000000006')->>'code'<>'idempotency_conflict' then raise exception 'altered replay accepted';end if;
 if has_function_privilege('authenticated','public.finalize_tournament_setup_pinned_v2(uuid,uuid,uuid,integer,boolean,jsonb,uuid)','execute')then raise exception 'browser execute granted';end if;
 if has_function_privilege('service_role','public.activate_tournament_setup_before_pins_0289(uuid,uuid,uuid,integer,uuid)','execute') or has_function_privilege('service_role','public.activate_tournament_setup_v2_legacy(uuid,uuid,uuid,integer,uuid)','execute') or has_function_privilege('service_role','public.activate_tournament_setup_v2_before_state_territory(uuid,uuid,uuid,integer,uuid)','execute') or has_function_privilege('service_role','public.activate_tournament_setup_v2_before_optional_contact(uuid,uuid,uuid,integer,uuid)','execute') then raise exception 'unpinned underlying activation exposed';end if;
end$$;
rollback;
